import sys

def _hook(event: str, args: tuple) -> None:          # installed once, removed never
    if event == "open":
        path, mode = args[0], args[1]
        if not _check(_CURRENT, mode, path):
            raise PermissionError(f"audited deny: {path}")
    elif event in ("socket.connect", "subprocess.Popen", "ctypes.dlopen"):
        if not _check(_CURRENT, event, args):
            raise PermissionError(f"audited deny: {event}")

sys.addaudithook(_hook)   # no API removes it; a raising hook cancels the operation
